/* C-3 authoring source for the two adaptive practice sets. Same compact form as c3-src-papers.js:
   o[0] is the KEY; e[0] null = use `why`. Order inside each module: gap items (easiest first),
   then 'most nearly means', then transitions. */
module.exports = {
a1: {
m1: [
{ id:"a1m1-01", t:"wic", d:"sci", lv:"B2", f:"fix", w:"exacerbate",
  p:"Overgrazing had already thinned the grass on the hillside, leaving patches of bare soil. A summer of heavy storms then ______ the erosion, washing away soil that the few remaining roots could no longer hold in place.",
  o:["exacerbated","alleviated","concealed","postponed"],
  e:[null,"*Alleviated* means made less severe; the storms washed away more soil, so the erosion got worse.","*Concealed* means hid; soil washed off a hillside is damage anyone could see.","*Postponed* means delayed; the storms sped up the loss of soil instead of putting it off."],
  why:"The grass was already thin, and the storms washed away even more soil: making an existing problem worse is exacerbating it.",
  h:"Was the erosion already happening, and did the storms help or hurt?" },
{ id:"a1m1-02", t:"wic", d:"lit", lv:"B2", f:"fit", w:null,
  p:"For eleven years, Bua's evenings at the lighthouse followed the same pattern: she lit the lamp at dusk, recorded the weather in the logbook and wound the clock before bed. The tasks had become so ______ that the night the lamp failed to light left her standing in the dark, unsure what to do next.",
  o:["routine","anomalous","incongruous","precarious"],
  e:[null,"*Anomalous* means breaking a pattern; the eleven years of tasks are the pattern, and only the failed lamp breaks it.","*Incongruous* means out of place; lighting the lamp and keeping the log are exactly what a lighthouse keeper does.","*Precarious* means unstable or likely to fail; the tasks had gone the same way every night for eleven years."],
  why:"The same tasks every evening for eleven years had become a fixed habit, which is why one change left her lost: they were routine.",
  h:"How often had Bua done these tasks, and in what way?" },
{ id:"a1m1-03", t:"wic", d:"hum", lv:"B2", f:"centre", w:"integral",
  p:"In the town's puppet theatre, the musician who sits beside the stage is far more than an accompanist. Her drum signals every entrance, sets the pace of each fight scene and even marks the narrator's pauses; without her, the puppeteers would have no way to keep time. She is ______ the performance.",
  o:["integral to","peripheral to","indifferent to","hostile to"],
  e:[null,"*Peripheral to* means at the edge of; the puppeteers could not keep time without her.","*Indifferent to* means not caring about; she signals entrances and sets the pace, so she is fully involved.","*Hostile to* means opposed to; she holds the performance together instead of working against it."],
  why:"She signals entrances, sets the pace and marks the pauses, and the show cannot run without her: she is an essential part of it, integral to it.",
  h:"What would happen to the performance without the musician?" },
{ id:"a1m1-04", t:"wic", d:"sci", lv:"C1", f:"claim", w:"substantiate",
  p:"A small company claimed that its new water filter removes nearly all microplastics from tap water, but for two years it published no test results. When an independent laboratory finally tested the filter, its findings did not ______ the claim: the filter removed fewer than half of the particles.",
  o:["substantiate","undermine","publicise","circumvent"],
  e:[null,"*Undermine* means weaken; a filter that removed fewer than half of the particles does weaken the claim, so 'did not undermine' is false.","*Publicise* means make widely known; test findings support or weaken a claim, they do not advertise it.","*Circumvent* means find a way round; the findings did not avoid the claim, they tested it."],
  why:"The filter removed fewer than half of the particles, so the findings gave no support to a claim of removing nearly all: they did not substantiate it.",
  h:"Did the laboratory's results back up the company's claim?" },
{ id:"a1m1-05", t:"wic", d:"lit", lv:"C1", f:"visible", w:"latent",
  p:"Throughout the first half of the story, Jasmine's anger at her older sister is ______: she smiles at family dinners and never raises her voice. Only when the sister sells their grandmother's piano does the resentment that had been building for years finally break into the open.",
  o:["latent","manifest","fleeting","feigned"],
  e:[null,"*Manifest* means plainly visible; she smiles and never raises her voice, so the anger does not show.","*Fleeting* means lasting only a moment; the resentment had been building for years.","*Feigned* means pretended; the anger is real, and it is her calm that is put on."],
  why:"Her anger exists and grows for years but stays hidden until the piano is sold: something present but not yet showing is latent.",
  h:"Is Jasmine's anger real? Can the family see it in the first half?" },
{ id:"a1m1-06", t:"wic", d:"hist", lv:"C1", f:"depend", w:"contingent-on",
  p:"Under an agreement recorded in one town's early archives, its right to hold a weekly fair was ______ its upkeep of the road to the river: if the road fell into disrepair, the fair could be transferred to a neighbouring town.",
  o:["contingent on","independent of","detrimental to","obscured by"],
  e:[null,"*Independent of* means not affected by; a neglected road could cost the town its fair.","*Detrimental to* means harmful to; holding the fair did not damage the road, it depended on it.","*Obscured by* means hidden by; the agreement states the condition openly."],
  why:"The town kept its fair only if it kept the road in repair, so the right depended on that condition: it was contingent on the upkeep.",
  h:"What could make the town lose its fair?" },
{ id:"a1m1-07", t:"wic", d:"sci", lv:"C2", f:"depend", w:"proxies-for",
  p:"Because a burrowing desert lizard is hard to count directly, field biologists in one survey counted the fresh tracks crossing sandy strips of ground each morning, using the number of tracks as ______ the number of lizards active nearby.",
  o:["a proxy for","a precursor to","a deterrent to","an exception to"],
  e:[null,"*A precursor to* comes before and leads to something; tracks are left after the lizards move, not before.","*A deterrent to* discourages something; counting tracks does not discourage lizards.","*An exception to* breaks a rule; the track count is used to estimate the lizards, not to break a pattern."],
  why:"The lizards cannot be counted directly, so their tracks are counted in their place: a measurable stand-in for something hard to measure is a proxy for it.",
  h:"Why count tracks instead of lizards?" },
{ id:"a1m1-08", t:"wic", d:"hum", lv:"C2", f:"visible", w:"belie",
  p:"The composer's short piano pieces, rarely longer than two minutes and written in a plain, almost childlike style, ______ their difficulty: performers report that the slow, exposed melodies leave nowhere to hide the smallest mistake in timing.",
  o:["belie","advertise","attest to","diminish"],
  e:[null,"*Advertise* means show openly; a plain, childlike style suggests ease, not difficulty.","*Attest to* means give evidence of; nothing in the short, simple look points to how hard the pieces are.","*Diminish* means make smaller; performers say the pieces remain very hard to play."],
  why:"Their short, simple look gives a false impression of ease, while performers find them very hard: when an appearance gives a false idea of something, it belies it.",
  h:"Do the pieces look as hard as they are to play?" },
{ id:"a1m1-09", t:"meaning", mw:"sound", d:"lit", lv:"C1", f:"claim", w:null,
  p:"Fah expected her grandmother to laugh at the plan to turn the empty shophouse into a reading room for the neighbourhood's children. Instead, the old woman listened, asked about the rent and the opening hours, and pronounced the idea sound.",
  o:["sensible","loud","deep","undamaged"],
  e:[null,"*Loud* links sound with noise; an idea is not something you hear.","*Deep* is the sense in *a sound sleep*; the grandmother is judging a plan, not describing sleep.","*Undamaged* is the sense in *a sound roof*; she judged that the plan would work after asking practical questions."],
  why:"After checking the rent and the hours, the grandmother judged the plan practical and well thought out: here sound means sensible.",
  h:"Why did the grandmother ask about the rent and the opening hours?" },
{ id:"a1m1-10", t:"transition", d:"sci", lv:"B2", f:"transition", w:null,
  p:"Researchers had expected the young octopuses in their study to need weeks to learn how to open a screw-top jar. That expectation proved far too cautious. ______ most of the animals opened the jar within two days, and one did so on its first attempt.",
  o:["In fact,","However,","Similarly,","Otherwise,"],
  e:[null,"*However* signals a contrast; the quick success agrees with the statement that the expectation was too cautious.","*Similarly* adds a parallel case; the last sentence is not a second, matching finding but stronger proof of the one before.","*Otherwise* means 'if not'; nothing in the passage sets up a condition."],
  why:"The last sentence confirms and strengthens the claim that the expectation was too cautious, with even more striking detail: emphasis is signalled by in fact.",
  h:"Does the last sentence pull against the one before it, or back it up even more strongly?" },
{ id:"a1m1-11", t:"transition", d:"hist", lv:"C1", f:"transition", w:"accordingly",
  p:"Surveys carried out in one river delta showed that its rice farmers were losing a growing share of each harvest to salt water pushed inland by high tides. ______ the farmers' cooperative began replacing part of its rice crop with salt-tolerant varieties and building low earth banks along the most exposed fields.",
  o:["Accordingly,","Similarly,","In other words,","Regardless,"],
  e:[null,"*Similarly* adds a parallel case; the farmers' actions are a response to the salt water, not another matching problem.","*In other words* restates what came before; replacing crops and building banks is new action.","*Regardless* means without paying attention to what came before; the cooperative acted precisely because of the salt water."],
  why:"The new crops and earth banks are a response that suits the salt-water losses: a fitting result is signalled by accordingly.",
  h:"Why did the cooperative change its crops and build banks?" },
{ id:"a1m1-12", t:"transition", d:"hum", lv:"C1", f:"transition", w:null,
  p:"Critics have praised the novelist for the way she uses weather to reflect her characters' moods. ______ storms in her books tend to arrive just as a character loses her temper, and fog settles whenever someone is keeping a secret.",
  o:["Specifically,","Nevertheless,","As a result,","In conclusion,"],
  e:[null,"*Nevertheless* signals a point that pulls against what came before; the second sentence supports the critics' praise.","*As a result* signals an effect; the storms and fog are not caused by the critics' praise.","*In conclusion* sums up an argument; the second sentence gives new, more exact detail instead of a summary."],
  why:"The second sentence states exactly how weather mirrors mood, storms with anger and fog with secrets: a more exact version of the previous claim is introduced by specifically.",
  h:"Is the second sentence a summary, a result, a contrast or a more exact statement of the first?" }
],
m2easy: [
{ id:"a1e-01", t:"wic", d:"hist", lv:"B2", f:"fix", w:"mitigate",
  p:"Workers at a small pottery spent long hours beside kilns that grew hotter than any oven. The owner could not make the kilns cooler, but she installed large fans and gave every worker a water bottle and frequent breaks, measures meant to ______ the risk of heatstroke.",
  o:["mitigate","increase","ignore","measure"],
  e:[null,"*Increase* means make bigger; fans, water and breaks protect workers from the heat.","*Ignore* means pay no attention to; the owner took several steps because of the risk.","*Measure* means find the size of; fans and water bottles reduce a risk, they do not measure it."],
  why:"The owner could not cool the kilns, so she took steps that made heatstroke less likely: lessening a harm without removing it is mitigating it.",
  h:"Were the fans and breaks meant to make the risk bigger, smaller or simply known?" },
{ id:"a1e-02", t:"wic", d:"sci", lv:"B2", f:"fit", w:"homogeneous",
  p:"The sand on the island's main beach is unusually ______: samples taken from the waterline, the dunes and the far end of the bay all contained grains of the same size, colour and mineral.",
  o:["homogeneous","varied","scarce","shifting"],
  e:[null,"*Varied* means of many different kinds; every sample had grains of the same size, colour and mineral.","*Scarce* means in short supply; the passage is about what the sand is like, not how much there is.","*Shifting* means moving about; the samples show sameness, not movement."],
  why:"Samples from three different places were alike in size, colour and mineral, so the sand is all of one kind: homogeneous.",
  h:"How similar were the samples from different parts of the beach?" },
{ id:"a1e-03", t:"wic", d:"lit", lv:"B2", f:"centre", w:null,
  p:"That summer the well behind the farmhouse ran almost dry, and water became so ______ that Pear and her sisters carried buckets from the river each morning and saved the washing-up water for the vegetable beds.",
  o:["scarce","abundant","murky","costly"],
  e:[null,"*Abundant* means plentiful; a nearly dry well and saved washing-up water show the opposite.","*Murky* means dark and dirty; nothing is said about the water's quality, only how little there was.","*Costly* means expensive; the sisters carried free river water, and the problem was how little there was."],
  why:"With the well nearly dry, the family had to fetch and save every drop: water was in short supply, which is scarce.",
  h:"Why did the sisters fetch water and save the washing-up water?" },
{ id:"a1e-04", t:"wic", d:"hum", lv:"B2", f:"centre", w:"peripheral",
  p:"In the documentary about the city's night market, the cooks and their food fill almost every scene. The market's history is ______ the film: it is mentioned in a single sentence near the end, and the director has said that it did not interest her.",
  o:["peripheral to","central to","harmful to","similar to"],
  e:[null,"*Central to* means at the heart of; the history gets one sentence, while the cooks fill almost every scene.","*Harmful to* means damaging to; the history does not hurt the film, it is simply given little space.","*Similar to* means like; the passage is about how much the film cares about the history, not about any likeness."],
  why:"The history gets one sentence and did not interest the director, so it sits at the edge of the film: peripheral to it.",
  h:"How much of the film is about the market's history?" },
{ id:"a1e-05", t:"wic", d:"sci", lv:"B2", f:"claim", w:"corroborate",
  p:"One student's science project suggested that bean plants grow faster under red light than under white light. Her teacher asked two other classes to repeat the experiment separately, using different plants and different rooms. Both classes found the same effect, results that ______ the student's finding.",
  o:["corroborated","contradicted","replaced","exaggerated"],
  e:[null,"*Contradicted* means went against; both classes found the same effect as the student.","*Replaced* means took the place of; the new results add to the student's finding instead of removing it.","*Exaggerated* means made something seem bigger than it is; the classes found the same effect, not a bigger one."],
  why:"Two separate classes repeated the experiment and found the same effect, giving independent support to the student's result: they corroborated it.",
  h:"Did the other classes work separately, and did they get the same result?" },
{ id:"a1e-06", t:"wic", d:"hist", lv:"C1", f:"attitude", w:"ambivalent",
  p:"Interviews with former students of a rural girls' school found that many were ______ about the scholarships that had sent them to study in the capital: they valued the education and the careers it opened, yet they regretted that so few of them had ever returned to work in their home villages.",
  o:["ambivalent","grateful","indifferent","ambiguous"],
  e:[null,"*Grateful* fits only the first half; the former students also regret that so few returned home.","*Indifferent* means without feeling; they both value the scholarships and regret one of their effects.","*Ambiguous* describes words or evidence with more than one meaning; it does not describe people's mixed feelings."],
  why:"The former students value the scholarships yet regret one of their effects: two opposed feelings about the same thing make them ambivalent.",
  h:"Find the positive feeling and the negative feeling in the interviews." },
{ id:"a1e-07", t:"wic", d:"sci", lv:"C1", f:"fit", w:"anomaly",
  p:"Every one of the two hundred seeds in the experiment sprouted within a week except one, which took a full month. The researchers treated the slow seed as ______ and examined it closely, eventually finding that its coat was twice as thick as the others'.",
  o:["an anomaly","a hypothesis","a standard","a control"],
  e:[null,"*A hypothesis* is a proposed explanation; the slow seed is a fact to be explained, not an explanation.","*A standard* is a normal example used for comparison; the slow seed was the one that did not behave normally.","*A control* is the group kept unchanged for comparison; all the seeds were treated alike, and only this one behaved differently."],
  why:"One seed in two hundred broke the clear pattern of sprouting within a week: a case that does not fit the pattern is an anomaly.",
  h:"How did the slow seed compare with the other one hundred and ninety-nine?" },
{ id:"a1e-08", t:"wic", d:"hist", lv:"C1", f:"visible", w:"opaque",
  p:"Residents complained that the old bus timetable was ______: it was written in codes that were explained nowhere on the page, so even regular passengers struggled to work out when the next bus would come. The new timetable lists every route in plain words.",
  o:["opaque","transparent","punctual","flexible"],
  e:[null,"*Transparent* means clear and easy to understand; that describes the new timetable, not the old coded one.","*Punctual* means on time; it describes buses, and the complaint was about reading the timetable.","*Flexible* means able to change easily; the problem was that passengers could not understand the codes."],
  why:"Unexplained codes left even regular passengers unable to read the timetable: something hard to understand because it is not made clear is opaque.",
  h:"What was hard for passengers to do with the old timetable?" },
{ id:"a1e-09", t:"meaning", mw:"fine", d:"lit", lv:"B2", f:"fit", w:null,
  p:"Mint's grandmother spun silk so fine that a whole scarf could be drawn through a ring. Visitors to the workshop often asked to hold the thread, and most were surprised that something so delicate did not break in their fingers.",
  o:["thin","healthy","sunny","acceptable"],
  e:[null,"*Healthy* is the sense in *I feel fine*; silk cannot be well or ill.","*Sunny* is the sense in *a fine day*; the passage is about thread, not weather.","*Acceptable* is the sense in *that's fine*; the ring and the delicate thread show the silk was very thin."],
  why:"A scarf that passes through a ring and thread that seems ready to break describe silk of very small thickness: here fine means thin.",
  h:"What does the ring tell you about the silk?" },
{ id:"a1e-10", t:"transition", d:"sci", lv:"B2", f:"transition", w:null,
  p:"Many species of bamboo grow very quickly, some adding more than half a metre in a single day during the rainy season. ______ the plants flower only rarely: in certain species, decades pass between one flowering and the next.",
  o:["However,","For example,","As a result,","Similarly,"],
  e:[null,"*For example* introduces an instance of the previous point; rare flowering is not an instance of fast growth.","*As a result* signals an effect; fast growth does not cause the plants to flower rarely.","*Similarly* adds a matching point; slow, rare flowering is the opposite of quick growth."],
  why:"Quick growth is set against very slow, rare flowering, so the second sentence pulls against the first: a contrast, signalled by however.",
  h:"Is the second fact like the first, caused by it, an example of it, or the opposite of it?" },
{ id:"a1e-11", t:"transition", d:"hist", lv:"B2", f:"transition", w:null,
  p:"In one hill town, the only bridge across the river was closed for repairs for most of a year, forcing traders to travel an extra twenty kilometres to reach the market. ______ many of them stopped coming, and the market shrank to half its usual size.",
  o:["As a result,","For example,","However,","In other words,"],
  e:[null,"*For example* introduces an instance; the shrinking market is an effect of the closure, not an example of it.","*However* signals a contrast; traders staying away is what a long detour would lead you to expect.","*In other words* restates; the second sentence adds new information about what happened next."],
  why:"The long detour caused traders to stay away and the market to shrink, so the second sentence follows from the first: a result.",
  h:"Did the market shrink because of the bridge closure?" },
{ id:"a1e-12", t:"transition", d:"hum", lv:"B2", f:"transition", w:null,
  p:"The poet often borrowed the language of science to describe ordinary household objects. ______ in one poem she describes a kettle coming to the boil as 'a small experiment in pressure', and in another she calls a folded towel 'a study in symmetry'.",
  o:["For example,","However,","In conclusion,","Instead,"],
  e:[null,"*However* signals a contrast; the kettle and towel lines show the habit instead of pulling against it.","*In conclusion* sums up an argument; the second sentence gives instances, not a summary.","*Instead* signals a replacement for what came before; the second sentence shows the same habit in action."],
  why:"The kettle and towel lines are particular cases of her habit of using scientific language for household things: an illustration is introduced by for example.",
  h:"Are the two lines particular cases of the habit described first?" }
],
m2hard: [
{ id:"a1h-01", t:"wic", d:"sci", lv:"C1", f:"centre", w:"inconsequential-to",
  p:"Early models of the lake's food web assumed that the tiny shrimp living in its mud were ______ the diet of the lake's trout, since few shrimp were ever found in the fish's stomachs. A recent study, however, showed that the shrimp are digested within minutes, so earlier counts badly underestimated them.",
  o:["inconsequential to","integral to","detrimental to","impervious to"],
  e:[null,"*Integral to* means essential to; that is what the recent study suggests, not what the early models assumed.","*Detrimental to* means harmful to; few shrimp in the stomachs suggested the shrimp hardly mattered, not that they did harm.","*Impervious to* means unaffected by; the early models judged how much the shrimp mattered to the diet, a different relationship."],
  why:"Because few shrimp turned up in the trout's stomachs, the early models assumed the shrimp made little difference to the diet: inconsequential to it.",
  h:"What did the low shrimp counts lead the early models to assume?" },
{ id:"a1h-02", t:"wic", d:"hum", lv:"C1", f:"centre", w:null,
  p:"Some critics feared that releasing the film online on the same day as its cinema premiere would empty the cinemas. In the event, the effect on ticket sales was ______: attendance in the first month differed from the studio's earlier releases by less than one per cent.",
  o:["negligible","pronounced","unprecedented","ambivalent"],
  e:[null,"*Pronounced* means strong and easy to notice; a difference of less than one per cent is hardly noticeable.","*Unprecedented* means never seen before; attendance was almost exactly like the studio's earlier releases.","*Ambivalent* describes people's mixed feelings; an effect on ticket sales cannot feel two ways about anything."],
  why:"Attendance changed by less than one per cent, so the effect was too small to matter: negligible.",
  h:"How big was the change in attendance?" },
{ id:"a1h-03", t:"wic", d:"hist", lv:"C1", f:"depend", w:"prevail-over",
  p:"Residents of a small river port were offered two designs for a new town hall: a modern glass building and a brick one in the style of the old warehouses. Despite the architects' enthusiasm for glass, the brick design ______ its rival by a wide margin, largely because residents wanted the hall to match the rest of the waterfront.",
  o:["prevailed over","succumbed to","capitulated to","conformed to"],
  e:[null,"*Succumbed to* means gave way to; the brick design won by a wide margin.","*Capitulated to* means surrendered to; the brick design won by a wide margin, so it was the glass design that lost.","*Conformed to* means followed the pattern of; the brick design matched the warehouses, not the glass rival."],
  why:"Residents chose the brick design by a wide margin, so it beat the glass proposal: it prevailed over its rival.",
  h:"Which design did the residents choose?" },
{ id:"a1h-04", t:"wic", d:"sci", lv:"C2", f:"fix", w:"precipitate",
  p:"Ecologists studying a coastal marsh found that decades of drainage for farmland had slowly dried and weakened its peat soils. The final collapse of the marsh's bird colony, however, was ______ by a single event: a fire, started by lightning in an unusually dry spring, that destroyed the nesting grounds in one night and drove the last birds away.",
  o:["precipitated","mitigated","forestalled","presaged"],
  e:[null,"*Mitigated* means made less severe; the fire destroyed the nesting grounds in a single night.","*Forestalled* means prevented by acting in advance; the fire brought the collapse about instead of preventing it.","*Presaged* means was a warning sign of something to come; the fire was no sign of a later collapse, it destroyed the nesting grounds itself."],
  why:"Drainage weakened the marsh over decades, but the fire made the colony collapse suddenly: the event that brings a collapse on sooner precipitates it.",
  h:"What was the slow, underlying cause, and what was the sudden final push?" },
{ id:"a1h-05", t:"wic", d:"hum", lv:"C2", f:"centre", w:null,
  p:"Scholars of the region's early theatre work with ______ evidence: only three scripts survive, none of them complete, and the few contemporary accounts describe the audiences in detail but say almost nothing about the plays themselves.",
  o:["a paucity of","a profusion of","a preponderance of","an affinity for"],
  e:[null,"*A profusion of* means a great quantity of; three incomplete scripts and a few accounts are very little.","*A preponderance of* means the larger share of; the passage is about how little evidence exists, not which kind outweighs another.","*An affinity for* means a natural liking for; nothing here concerns what the scholars like."],
  why:"Only three incomplete scripts and a few unhelpful accounts survive, so the evidence is very scarce: a paucity of it.",
  h:"How much evidence about the plays survives?" },
{ id:"a1h-06", t:"wic", d:"hist", lv:"C2", f:"claim", w:"buttress",
  p:"The historian's first article argued that the guild's records had been deliberately altered, but reviewers noted that she relied on a single suspicious entry. In a second article she ______ her case, setting out forty further entries in which the ink, the handwriting and the dates all failed to match.",
  o:["buttressed","recanted","belied","circumscribed"],
  e:[null,"*Recanted* means publicly took back; she kept her argument and added evidence for it.","*Belied* means gave a false picture of; forty further examples present her case more fully, not falsely.","*Circumscribed* means restricted or narrowed; adding forty further entries widens the support instead of narrowing the case."],
  why:"Reviewers found her evidence thin, so she added forty more suspect entries to support and strengthen her argument: she buttressed it.",
  h:"What did the second article add to the first argument?" },
{ id:"a1h-07", t:"wic", d:"hist", lv:"C2", f:"fit", w:"incongruous-with",
  p:"To the surprise of the team excavating an ancient lakeside village, the oldest layer contained a finely polished jade blade, an object far more sophisticated than the rough stone scrapers found around it. Its quality seemed so ______ the rest of the layer that some team members suspected it had slipped down from a later level.",
  o:["incongruous with","commensurate with","contingent on","tantamount to"],
  e:[null,"*Commensurate with* means matching in size or level; the blade was far finer than the scrapers around it.","*Contingent on* means depending on; the blade's quality did not depend on the layer, it seemed out of place in it.","*Tantamount to* means equivalent to; the point is that the blade was unlike its surroundings."],
  why:"A polished blade among rough scrapers looked so out of place that some suspected it came from a later layer: it was incongruous with its surroundings.",
  h:"Did the blade look like the other objects in its layer?" },
{ id:"a1h-08", t:"meaning", mw:"arrested", d:"lit", lv:"C1", f:"fix", w:null,
  p:"The argument between the two sisters had been growing louder for an hour when their grandmother's sudden laugh from the next room arrested it. Both girls fell silent, looked at each other and, despite themselves, began to smile.",
  o:["halted","seized","captured","attracted"],
  e:[null,"*Seized* reflects the police sense of arrest; nobody takes hold of an argument.","*Captured* also reflects the police sense; the sisters were not taken prisoner, they stopped arguing.","*Attracted* reflects *arrest someone's attention*; the laugh did not draw the argument towards it, it ended it."],
  why:"After the laugh, both girls fell silent, so the argument stopped: here arrested means halted.",
  h:"What happened to the argument straight after the laugh?" },
{ id:"a1h-09", t:"meaning", mw:"entertain", d:"lit", lv:"C2", f:"attitude", w:null,
  p:"For months Kwan refused even to entertain the idea of selling the bakery her mother had founded. It was only after a winter of empty shelves and unpaid bills that she agreed to meet the buyer, and even then she said very little.",
  o:["consider","amuse","host","perform"],
  e:[null,"*Amuse* is the sense in *entertain the children*; an idea cannot be amused.","*Host* is the sense in *entertain guests*; Kwan is refusing to think about a proposal, not to receive visitors.","*Perform* reflects entertaining an audience; Kwan is refusing to think about a proposal, not to put on a show."],
  why:"Only after the hard winter does she agree to meet the buyer, so at first she would not even think about selling: here entertain means consider.",
  h:"What did Kwan finally agree to do, and what had she refused before?" },
{ id:"a1h-10", t:"transition", d:"sci", lv:"C1", f:"transition", w:null,
  p:"In the first group of bean plants, which were watered every day, the roots stayed within a few centimetres of the soil surface. ______ the roots of plants watered only once a week grew deep into the pot, reaching for moisture that had drained to the bottom.",
  o:["By contrast,","As a result,","Specifically,","Likewise,"],
  e:[null,"*As a result* signals an effect of the first sentence; the deep roots belong to a different group and are not caused by daily watering.","*Specifically* gives a more exact version of the first sentence; the second sentence describes a different group.","*Likewise* signals a matching case; deep roots are the opposite of shallow ones."],
  why:"Shallow roots in the daily-watered group are set against deep roots in the weekly group: two groups compared as opposites call for by contrast.",
  h:"Does the second group behave like the first group or differently?" },
{ id:"a1h-11", t:"transition", d:"hist", lv:"C2", f:"transition", w:null,
  p:"The historian argues that the town's records give a reliable picture of its trade in the seventeenth century. ______ the records omit the many small sales made at the weekly market, but she shows that such sales together made up only a tiny share of the town's commerce.",
  o:["Granted,","Therefore,","For instance,","Similarly,"],
  e:[null,"*Therefore* signals a result; a gap in the records does not follow from the claim that they are reliable.","*For instance* introduces an example; a gap in the records is not an example of their reliability.","*Similarly* adds a matching point; the omission is a weakness, set against the claim of reliability."],
  why:"The sentence admits a weakness in the records before the historian shows that it hardly matters: conceding a point while keeping the main claim is signalled by granted.",
  h:"Does the second sentence admit a weakness and then answer it?" },
{ id:"a1h-12", t:"transition", d:"hum", lv:"C2", f:"transition", w:"that-said",
  p:"The documentary's interviews with former mill workers are its great strength, giving voice to people whom earlier histories of the industry ignored. ______ the film rarely checks these memories against the mills' own written records, some of which tell a different story.",
  o:["That said,","Indeed,","Specifically,","For example,"],
  e:[null,"*Indeed* strengthens the previous point; the second sentence criticises the film's handling of the memories instead of adding praise.","*Specifically* gives a more exact version of the previous point; the second sentence raises a new weakness.","*For example* introduces an instance; failing to check memories against records is not an instance of giving voice to workers."],
  why:"The praise for the interviews stands, and the second sentence adds a limit: the film rarely checks them. Keeping one point while qualifying it is a concession: that said.",
  h:"Does the second sentence add more praise, or keep the praise while pointing out a weakness?" }
]
},

a2: {
m1: [
{ id:"a2m1-01", t:"wic", d:"hist", lv:"B2", f:"fix", w:"ameliorate",
  p:"For years, patients at the city's only hospital had faced waits of six hours or more. A new clinic in the eastern district could not solve the problem on its own, but by treating minor injuries close to home it noticeably ______ conditions in the hospital's crowded waiting rooms.",
  o:["ameliorated","worsened","concealed","recorded"],
  e:[null,"*Worsened* means made worse; taking minor injuries away from the hospital eases the crowding.","*Concealed* means hid; the clinic changed the conditions, it did not hide them.","*Recorded* means wrote down; the clinic treated patients, which changed the conditions instead of documenting them."],
  why:"The clinic did not solve the overcrowding but made the bad conditions better: improving a bad situation without curing it is ameliorating it.",
  h:"Did the clinic make the waiting rooms better or worse, and did it solve the problem?" },
{ id:"a2m1-02", t:"wic", d:"sci", lv:"B2", f:"fit", w:"disparate",
  p:"At first glance, the two species of fish could hardly look more ______: one is long, silver and fast, the other round, spotted and slow. Genetic tests show, however, that they are close relatives that separated only a few thousand years ago.",
  o:["disparate","alike","related","comparable"],
  e:[null,"*Alike* means similar; the long, silver, fast fish and the round, spotted, slow one are described as opposites.","*Related* is what the genetic tests show; the first sentence describes how unrelated the fish look.","*Comparable* means similar enough to be compared; the descriptions show two fish that look nothing alike."],
  why:"Every feature listed differs between the two fish, so they look entirely different in kind: disparate, an impression the genetic tests then overturn.",
  h:"Compare the two descriptions after the colon." },
{ id:"a2m1-03", t:"wic", d:"lit", lv:"B2", f:"attitude", w:null,
  p:"When Fon asked her piano teacher what she thought of the performance, she expected the usual gentle praise. Instead, the teacher was ______: the opening was rushed, she said, the middle section was dull, and the ending was the best playing Fon had ever done.",
  o:["candid","evasive","flattering","sanguine"],
  e:[null,"*Evasive* means avoiding a direct answer; the teacher gave a clear verdict on every section.","*Flattering* means giving too much praise; that is the gentle praise Fon expected, and the teacher did not give it.","*Sanguine* means confident that things will turn out well; the teacher is judging a past performance, not looking ahead."],
  why:"Instead of gentle praise, the teacher said plainly what was weak and what was strong: honest and direct is candid.",
  h:"How did the teacher's answer differ from the praise Fon expected?" },
{ id:"a2m1-04", t:"wic", d:"hum", lv:"C1", f:"visible", w:"manifest",
  p:"The architect's love of the countryside where she grew up is ______ almost every building she designed: low roofs that echo the shape of the hills, walls of local clay, and windows placed to frame views of the fields.",
  o:["manifest in","incidental to","alien to","obscured by"],
  e:[null,"*Incidental to* means a minor, chance part of; the love shows in the roofs, the walls and the windows of almost every building.","*Alien to* means foreign to; the buildings are full of the countryside, not opposed to it.","*Obscured by* means hidden by; hill-shaped roofs and clay walls make the love easy to see."],
  why:"Roofs, walls and windows all plainly show her love of the countryside: a quality that is plainly visible in something is manifest in it.",
  h:"Is her love of the countryside hard or easy to see in the buildings?" },
{ id:"a2m1-05", t:"wic", d:"sci", lv:"C1", f:"claim", w:"tenuous",
  p:"A study reported a link between the colour of a classroom's walls and students' test scores, but the link is ______: the study compared only four classrooms, and the rooms with higher scores also had newer computers and smaller classes.",
  o:["tenuous","robust","causal","novel"],
  e:[null,"*Robust* means strong and reliable; four classrooms and other differences make the link weak.","*Causal* means one thing causes the other; newer computers and smaller classes could explain the scores, so no cause is shown.","*Novel* means new and original; the passage is about how weak the evidence is, not how new the idea is."],
  why:"Only four classrooms were compared, and other differences could explain the scores, so the link is very weakly supported: tenuous.",
  h:"What problems with the study does the passage list?" },
{ id:"a2m1-06", t:"wic", d:"hist", lv:"C1", f:"claim", w:"attest-to",
  p:"No contract or letter records the agreement between the two villages that shared the hillside spring. Yet the stone channel that divides its water into two equal streams, and the matching marks carved by each village on its side, ______ a long and carefully kept arrangement.",
  o:["attest to","detract from","depart from","dispense with"],
  e:[null,"*Detract from* means make something seem less; the channel and marks make the arrangement clearer, not smaller.","*Depart from* means move away from or break with; the equal streams carry out the arrangement instead of breaking it.","*Dispense with* means do without; the channel is the arrangement in action, not a way of doing without it."],
  why:"The equal channel and matching marks are physical evidence of a lasting agreement: when objects show that something existed, they attest to it.",
  h:"With no written record, what shows that the arrangement existed?" },
{ id:"a2m1-07", t:"wic", d:"sci", lv:"C2", f:"fix", w:"stymie",
  p:"Biologists hoping to film a deep-sea squid in its natural habitat have repeatedly been ______: the bright lamps needed for filming drive the animal away, while the dim red light it cannot see is too weak for most cameras.",
  o:["stymied","vindicated","sanctioned","compounded"],
  e:[null,"*Vindicated* means shown to be right; the colon describes efforts that keep failing.","*Sanctioned* means officially approved or penalised; no authority is involved, only a problem with light.","*Compounded* means made worse and is used of difficulties, not of people; the biologists are blocked, not intensified."],
  why:"Bright light scares the squid and dim light is too weak to film by, so the biologists' efforts keep being blocked: they have been stymied.",
  h:"What keeps happening when the biologists try to film?" },
{ id:"a2m1-08", t:"wic", d:"hum", lv:"C2", f:"centre", w:"immaterial-to",
  p:"In the debate society's rules, a speaker's score depends only on the strength of her argument and the evidence she gives. Whether she personally agrees with the side she has been assigned is ______ the judges, who are told never to ask.",
  o:["immaterial to","integral to","obvious to","indebted to"],
  e:[null,"*Integral to* means essential to; the score depends only on argument and evidence, not on personal belief.","*Obvious to* means easy for someone to see; the judges never ask, and the point is that it does not matter to them.","*Indebted to* means owing thanks to; a speaker's private opinion owes nothing to the judges."],
  why:"Scores depend only on argument and evidence, and judges never ask about belief, so it makes no difference to them: it is immaterial to them.",
  h:"What do the judges base the score on?" },
{ id:"a2m1-09", t:"meaning", mw:"keen", d:"lit", lv:"C1", f:"attitude", w:null,
  p:"Mali had read every book in the village library about the rainforest, so when her aunt mentioned that a team of botanists needed a helper for the summer, she was keen to go. She packed her bag that same evening, before anyone had even asked her.",
  o:["eager","sharp","cold","perceptive"],
  e:[null,"*Sharp* is the sense in *a keen blade*; Mali is not cutting anything.","*Cold* is the sense in *a keen wind*; the passage is about her wish to join the team.","*Perceptive* is the sense in *a keen eye*; packing her bag at once shows desire, not sharp observation."],
  why:"She had read everything on the subject and packed that same evening, so she wanted very much to go: here keen means eager.",
  h:"What does packing her bag that same evening show about Mali?" },
{ id:"a2m1-10", t:"transition", d:"sci", lv:"B2", f:"transition", w:null,
  p:"Snow reflects most of the sunlight that falls on it, while bare rock and soil absorb much of it. ______ when snow cover shrinks in spring, the exposed ground warms quickly, which in turn melts the snow around it even faster.",
  o:["Therefore,","However,","Similarly,","In other words,"],
  e:[null,"*However* signals a contrast; the warming ground follows from the facts given, it does not go against them.","*Similarly* adds a parallel fact; the second sentence draws a consequence from the first.","*In other words* restates; the second sentence adds a new consequence, the faster melting."],
  why:"Because bare ground absorbs the sunlight that snow reflects, losing snow cover makes the ground warm: the second sentence follows from the first, so a result word fits.",
  h:"Does the spring warming follow from the facts about sunlight?" },
{ id:"a2m1-11", t:"transition", d:"hum", lv:"C1", f:"transition", w:"that-said",
  p:"The festival's new outdoor stage has made its concerts far easier to attend: it holds three times as many people as the old hall, and tickets now cost half as much. ______ the open-air sound is noticeably weaker, and the quietest pieces are often lost beneath the noise of the street.",
  o:["That said,","In other words,","Likewise,","For instance,"],
  e:[null,"*In other words* restates; weaker sound is a new point, and a drawback, not the same praise again.","*Likewise* adds a matching point; the weaker sound goes against the praise, so it does not match.","*For instance* introduces an example of the previous point; weaker sound is not an example of easier access."],
  why:"The gains in space and price still stand, and the second sentence adds a drawback that limits them: a concession, which that said signals.",
  h:"Does the weaker sound cancel the benefits, repeat them or limit them?" },
{ id:"a2m1-12", t:"transition", d:"hist", lv:"C1", f:"transition", w:null,
  p:"For decades, two neighbouring towns argued over who should pay to repair the bridge between them, and several plans were proposed and abandoned. ______ they agreed to share the cost equally, and the bridge reopened after a year of work.",
  o:["Ultimately,","Conversely,","For example,","Similarly,"],
  e:[null,"*Conversely* introduces the reverse of the previous point; the agreement ends the argument, it is not its reverse.","*For example* introduces an instance; the final agreement is not an example of the arguing.","*Similarly* adds a matching point; agreement after decades of dispute is the end of a sequence, not a parallel."],
  why:"After decades of argument and abandoned plans, the agreement came last: an outcome at the end of a long process is introduced by ultimately.",
  h:"Where does the agreement come in the story of the dispute?" }
],
m2easy: [
{ id:"a2e-01", t:"wic", d:"sci", lv:"B2", f:"centre", w:"integral",
  p:"In a honeybee colony, the worker bees that fan their wings at the entrance keep the hive cool on hot days. Without them, the wax combs would soften and the young bees inside would die, so the fanning workers are ______ the colony's survival.",
  o:["integral to","harmful to","separate from","unrelated to"],
  e:[null,"*Harmful to* means damaging to; the fanning keeps the colony alive.","*Separate from* means apart from; the fanning workers are part of the colony and keep it cool.","*Unrelated to* means not connected with; without the fanning workers, the young bees would die."],
  why:"Without the fanning workers the combs soften and the young die, so they are an essential part of the colony's survival: integral to it.",
  h:"What would happen to the colony without the fanning workers?" },
{ id:"a2e-02", t:"wic", d:"hist", lv:"B2", f:"centre", w:null,
  p:"Records of daily life in the mountain villages before 1900 are ______: a handful of letters, two tax lists and a single diary are all that historians have been able to find.",
  o:["sparse","plentiful","accurate","recent"],
  e:[null,"*Plentiful* means existing in large amounts; a handful of letters and one diary is very little.","*Accurate* means correct; the passage is about how few records exist, not whether they are right.","*Recent* means from a short time ago; the records date from before 1900."],
  why:"A handful of letters, two lists and one diary are all that survive, so the records are few and thinly spread: sparse.",
  h:"How many records have historians found?" },
{ id:"a2e-03", t:"wic", d:"lit", lv:"B2", f:"attitude", w:"sanguine",
  p:"The rest of the team groaned when the rain began on the morning of the race, but their captain, Prang, remained ______. 'We trained in worse weather than this all winter,' she reminded them, tightening her laces. 'The others will slow down; we won't.'",
  o:["sanguine","gloomy","furious","puzzled"],
  e:[null,"*Gloomy* means without hope; Prang expects her team to do better than the others.","*Furious* means very angry; she calmly tightens her laces and encourages the team.","*Puzzled* means confused; she explains clearly why the rain will not hurt them."],
  why:"While the others groan, Prang calmly expects her team to do well in the rain: confidence about a good outcome when others are worried is being sanguine.",
  h:"How does Prang expect the race to go?" },
{ id:"a2e-04", t:"wic", d:"hum", lv:"B2", f:"claim", w:"substantiate",
  p:"A student's essay claimed that the town's oldest bridge was built in a single summer. Her teacher praised the idea but asked her to ______ it with evidence, so the student spent a week in the library collecting old maps, letters and newspaper reports from that year.",
  o:["substantiate","abandon","repeat","exaggerate"],
  e:[null,"*Abandon* means give up; the student went looking for evidence for her claim, not dropping it.","*Repeat* means say again; the teacher wanted proof, not the same claim a second time.","*Exaggerate* means make something seem bigger than it is; collecting maps and letters is gathering proof."],
  why:"The teacher wanted the claim supported with facts, so the student collected maps, letters and reports: providing evidence that a claim is true is substantiating it.",
  h:"What did the student collect, and why?" },
{ id:"a2e-05", t:"wic", d:"sci", lv:"C1", f:"depend", w:"contingent-on",
  p:"In a greenhouse trial, the tomato plants produced fruit only when bumblebees were allowed inside; when the bees were kept out, the flowers dropped off without forming fruit. The harvest was therefore ______ the presence of the bees.",
  o:["contingent on","indifferent to","unaffected by","responsible for"],
  e:[null,"*Indifferent to* describes a person who does not care; a harvest has no feelings.","*Unaffected by* means not changed by; without the bees there was no fruit at all.","*Responsible for* means the cause of; the bees made the harvest possible, not the other way round."],
  why:"Fruit formed only when the bees were present, so the harvest happened only on that condition: it was contingent on the bees.",
  h:"What happened to the flowers when the bees were kept out?" },
{ id:"a2e-06", t:"wic", d:"lit", lv:"C1", f:"visible", w:"latent",
  p:"As a child, Nina showed no interest in the garden her mother tended so carefully. Years later, when she inherited the house, a ______ love of growing things seemed to wake in her: within a year she had planted roses, beans and a small orchard.",
  o:["latent","visible","famous","reluctant"],
  e:[null,"*Visible* means easy to see; as a child Nina showed no interest at all, so the love did not show.","*Famous* means known to many people; nothing suggests anyone knew of her love of gardening.","*Reluctant* means unwilling; she planted roses, beans and an orchard within a year, which is eager work."],
  why:"The love seems to wake in her, so it was there all along but hidden: something present but not yet showing is latent.",
  h:"The love 'wakes' in her. Where was it before that?" },
{ id:"a2e-07", t:"wic", d:"hist", lv:"C1", f:"fix", w:"mitigate",
  p:"In a port city where floods regularly reached the market streets, the council raised the pavements and dug wide drains along the waterfront. The floods still came each year, but these measures helped to ______ their effect on the traders, who now lost only a day's business instead of a week's.",
  o:["mitigate","intensify","predict","document"],
  e:[null,"*Intensify* means make stronger; traders now lose a day instead of a week, so the effect is weaker.","*Predict* means say in advance; raised pavements and drains act on floods, they do not forecast them.","*Document* means record; the measures changed the floods' effect instead of recording it."],
  why:"The floods still came but did less harm, costing a day instead of a week: lessening a harm without preventing it is mitigating it.",
  h:"Did the floods stop, or did their effect become smaller?" },
{ id:"a2e-08", t:"wic", d:"sci", lv:"C1", f:"fit", w:null,
  p:"The team expected birds on the windier islands to have shorter wings, reasoning that shorter wings would be easier to control in strong gusts. The measurements they collected were ______ that expectation: on every one of the six windy islands, average wing length was shorter than on the sheltered ones.",
  o:["consistent with","contrary to","irrelevant to","dependent on"],
  e:[null,"*Contrary to* means opposed to; shorter wings on every windy island are exactly what was expected.","*Irrelevant to* means unconnected with; wing measurements are the very evidence that tests the expectation.","*Dependent on* means relying on; the measurements were taken to test the expectation, they did not rely on it."],
  why:"Every windy island had shorter-winged birds, just as expected, so the measurements agreed with the expectation: they were consistent with it.",
  h:"Did the measurements match what the team expected?" },
{ id:"a2e-09", t:"meaning", mw:"bright", d:"lit", lv:"B2", f:"attitude", w:null,
  p:"Everyone in the class knew that Aom was bright: she solved the teacher's hardest puzzles in minutes and could explain her method so clearly that her classmates understood it the first time.",
  o:["clever","shining","cheerful","colourful"],
  e:[null,"*Shining* is the sense in *a bright light*; the passage is about how Aom thinks.","*Cheerful* is the sense in *a bright smile*; solving puzzles quickly shows intelligence, not mood.","*Colourful* is the sense in *bright clothes*; nothing is said about how she looks."],
  why:"Solving the hardest puzzles in minutes and explaining them clearly show intelligence: here bright means clever.",
  h:"What evidence does the passage give about Aom?" },
{ id:"a2e-10", t:"transition", d:"hum", lv:"B2", f:"transition", w:null,
  p:"Many of the town's oldest buildings were made from materials that had been used before. ______ the walls of the market hall contain bricks stamped with the name of a factory that closed long before the hall was built.",
  o:["For example,","In contrast,","Nevertheless,","Instead,"],
  e:[null,"*In contrast* signals a difference; the market hall's bricks fit the general point about reused materials.","*Nevertheless* signals a point that goes against what came before; the bricks support the first sentence.","*Instead* signals a replacement; the second sentence gives a case of reuse, not an alternative to it."],
  why:"Old bricks from a closed factory in the market hall are one particular case of buildings made from reused materials: an illustration, introduced by for example.",
  h:"Is the market hall a particular case of the general point?" },
{ id:"a2e-11", t:"transition", d:"sci", lv:"B2", f:"transition", w:null,
  p:"Scientists once believed that the tiny fish in the cave lake found food by sight. Tests in total darkness showed that this was not the case. ______ the fish locate their prey by sensing the faint vibrations it makes in the water.",
  o:["Instead,","For example,","Similarly,","As a result,"],
  e:[null,"*For example* introduces an instance; sensing vibrations is not an example of finding food by sight.","*Similarly* adds a matching point; the second method replaces the first, it does not match it.","*As a result* signals an effect of the tests; the fish used vibrations long before anyone tested them."],
  why:"The tests ruled out sight, and the last sentence gives the method that takes its place: a replacement for a rejected idea is introduced by instead.",
  h:"Once sight is ruled out, what does the last sentence offer?" },
{ id:"a2e-12", t:"transition", d:"hist", lv:"B2", f:"transition", w:null,
  p:"In the late nineteenth century, a new railway line made it possible to carry fresh fish from the coast to one region's inland towns in a single day. ______ fish, once a rare luxury in those towns, became a common part of everyday meals.",
  o:["As a result,","For instance,","However,","Similarly,"],
  e:[null,"*For instance* introduces an example; fish becoming common is an effect of the railway, not an example of it.","*However* signals a contrast; fish becoming common is what faster transport would lead you to expect.","*Similarly* adds a parallel case; the second sentence describes a consequence, not a matching event."],
  why:"Fast transport from the coast made fish easy to get inland, so it became common: the second sentence follows from the first, a result.",
  h:"Did fish become common because of the railway?" }
],
m2hard: [
{ id:"a2h-01", t:"wic", d:"lit", lv:"C1", f:"visible", w:"opaque",
  p:"Throughout the novel, the narrator's aunt makes decisions that baffle her family: she sells the farm, buys it back a year later and then gives it away. Her reasons remain ______ to the very last page, for she explains herself to no one and leaves no letters behind.",
  o:["opaque","facile","abrasive","outspoken"],
  e:[null,"*Facile* means too simple or shallow; we never learn her reasons, so we cannot judge how deep they are.","*Abrasive* means harsh and rude in manner; it describes how someone behaves, not reasons nobody can see.","*Outspoken* means saying openly what you think; the aunt explains herself to no one."],
  why:"The aunt explains herself to no one and leaves no letters, so nobody can see into her reasons: they remain opaque.",
  h:"Can the family, or the reader, work out why she acts as she does?" },
{ id:"a2h-02", t:"wic", d:"hist", lv:"C1", f:"fix", w:null,
  p:"The first printing of the town's history contained more than forty errors in names and dates, which readers listed in letters to the publisher. The second printing ______ every one of them, and the publisher added a page thanking the readers who had pointed them out.",
  o:["rectified","ameliorated","sanctioned","perpetuated"],
  e:[null,"*Ameliorated* means made a bad situation better without necessarily curing it; each error was corrected outright, not merely improved.","*Sanctioned* means officially approved; the publisher corrected the errors and thanked the readers who found them.","*Perpetuated* means kept something going; the errors were removed from the second printing."],
  why:"Every one of the forty errors was corrected, so the problem was put right completely: to correct a mistake fully is to rectify it.",
  h:"Were the errors made a little better, kept, or fully corrected?" },
{ id:"a2h-03", t:"wic", d:"sci", lv:"C1", f:"claim", w:"corroborate",
  p:"The astronomer's claim that a faint star dims every eleven days rested at first on her own observations from a single small telescope. The claim has since been ______ data from two independent observatories, both of which recorded the same eleven-day pattern.",
  o:["corroborated by","contravened by","collaborated on","circumvented by"],
  e:[null,"*Contravened by* means broken or opposed by; both observatories recorded the same pattern.","*Collaborated on* means worked on together, which only people do; data cannot collaborate, and the claim is supported, not worked on.","*Circumvented by* means avoided or got round; the new data test the claim directly and agree with it."],
  why:"Two independent observatories recorded the same eleven-day pattern, giving separate support to the claim: it has been corroborated by their data.",
  h:"Did the observatories work independently, and did they agree with the astronomer?" },
{ id:"a2h-04", t:"wic", d:"hum", lv:"C2", f:"attitude", w:"ambivalent",
  p:"The poet's letters reveal a deep ______ the city where she spent her adult life: she praised its libraries and theatres in almost every letter, yet she called its crowded streets a prison and longed, she wrote, for the silence of the hills.",
  o:["ambivalence about","deference to","antipathy towards","affinity for"],
  e:[null,"*Deference to* means respectful obedience to; she judges the city freely, praising some things and condemning others.","*Antipathy towards* means strong dislike of; it fits the complaints but not the praise of the libraries and theatres.","*Affinity for* means a natural liking for; it fits the praise but not the prison image and the longing for the hills."],
  why:"She both praises the city and calls it a prison, holding opposite attitudes at once: two opposed feelings about one thing are ambivalence.",
  h:"Find her praise and her complaints. Which option covers both?" },
{ id:"a2h-05", t:"wic", d:"sci", lv:"C2", f:"centre", w:"dearth",
  p:"Models of how one deep ocean basin stores heat remain uncertain largely because of ______ direct measurements: until recently, only three instruments sampled the water below two thousand metres, leaving most of the basin unmeasured for years at a time.",
  o:["a dearth of","a surfeit of","a semblance of","an aversion to"],
  e:[null,"*A surfeit of* means more than enough of; three instruments for a whole basin is far too few.","*A semblance of* means an outward appearance of; the measurements are real but scarce, not an imitation.","*An aversion to* means a strong dislike of; nothing suggests scientists dislike measuring, only that there were too few instruments."],
  why:"Only three instruments sampled the deep water, so most of the basin went unmeasured: too few measurements is a dearth of them.",
  h:"Read after the colon: how many instruments were there?" },
{ id:"a2h-06", t:"wic", d:"hist", lv:"C2", f:"claim", w:"tenuous",
  p:"The historian asserts, with complete confidence, that the two merchant families were linked by marriage, but her case rests on a single letter in which an unnamed 'cousin' is mentioned once. The connection is not impossible, yet most of her colleagues regard it as ______.",
  o:["tenuous","untenable","tentative","conclusive"],
  e:[null,"*Untenable* means impossible to defend; the passage says the connection is not impossible.","*Tentative* means offered cautiously; the historian asserts the link with complete confidence.","*Conclusive* means settling the matter; one letter mentioning an unnamed cousin settles nothing."],
  why:"The link is still possible but rests on one vague letter, so its support is very weak: still standing, but only just, is tenuous.",
  h:"What does 'not impossible' rule out, and how confident is the historian herself?" },
{ id:"a2h-07", t:"wic", d:"sci", lv:"C2", f:"depend", w:null,
  p:"The researchers found that the plant's resistance to drought is ______ a fungus living in its roots: the fungus does not supply water itself, but it releases a chemical that signals the plant to close the pores in its leaves, so less water escapes.",
  o:["mediated by","impervious to","detrimental to","antithetical to"],
  e:[null,"*Impervious to* means unaffected by; the fungus plays an active part in the plant's resistance.","*Detrimental to* means harmful to; the fungus helps the plant hold on to water.","*Antithetical to* means directly opposed to; the fungus works with the plant's resistance, not against it."],
  why:"The fungus acts as a go-between: its chemical signal leads the plant to close its pores. A result brought about through an in-between factor is mediated by it.",
  h:"Does the fungus act directly, or through a step in between?" },
{ id:"a2h-08", t:"meaning", mw:"betrayed", d:"lit", lv:"C1", f:"visible", w:null,
  p:"Fern insisted that she was not worried about the results, and her voice was perfectly steady. Her hands, however, betrayed her unease: she had folded and unfolded the same envelope so many times that its corners had gone soft.",
  o:["revealed","abandoned","deceived","denounced"],
  e:[null,"*Abandoned* links betray with disloyalty, deserting someone; her hands did not desert her unease, they showed it.","*Deceived* is the sense of being disloyal through lies; her hands showed the truth instead of hiding it.","*Denounced* reflects the sense of informing on someone; her hands accused nobody, they simply showed how she felt."],
  why:"Fern's steady voice hid her worry, but her restless hands showed it: here betrayed means revealed what she was trying to hide.",
  h:"What did her hands show that her voice did not?" },
{ id:"a2h-09", t:"meaning", mw:"tempered", d:"lit", lv:"C2", f:"claim", w:null,
  p:"Ms Wanida's review of the students' exhibition was generous, but she tempered her praise with a warning: several of the paintings, she wrote, relied so heavily on a single bright colour that they began to look alike.",
  o:["moderated","provoked","hardened","postponed"],
  e:[null,"*Provoked* links the word with losing your temper; the warning calmed the praise instead of angering anyone.","*Hardened* reflects tempering steel; the warning made her praise less strong, not tougher.","*Postponed* means delayed; she gave the praise and the warning together."],
  why:"The warning about repeated colour made her generous praise less absolute: to temper praise is to moderate it.",
  h:"Did the warning make the praise stronger, angrier or more limited?" },
{ id:"a2h-10", t:"transition", d:"sci", lv:"C1", f:"transition", w:null,
  p:"The new variety of rice tolerates flooding far better than older varieties. ______ in field trials it survived being completely underwater for two weeks, while the older plants died after four days.",
  o:["Indeed,","Nonetheless,","Conversely,","Regardless,"],
  e:[null,"*Nonetheless* signals a concession against the previous point; the trial result supports the claim about flooding.","*Conversely* introduces the reverse of the previous point; surviving two weeks underwater confirms flood tolerance.","*Regardless* means without paying attention to what came before; the trial is directly about the flooding just mentioned."],
  why:"Surviving two weeks underwater strongly confirms the claim that the rice tolerates flooding: a sentence that reinforces the previous one is introduced by indeed.",
  h:"Does the trial result weaken, reverse or reinforce the first sentence?" },
{ id:"a2h-11", t:"transition", d:"hist", lv:"C2", f:"transition", w:null,
  p:"The town's archive lost most of its nineteenth-century records in a fire, and the few that survive are badly damaged. ______ a team of volunteers has managed to reconstruct the history of the town's market by piecing together scorched account books, shop signs and the memories of the oldest residents.",
  o:["Nonetheless,","Therefore,","Specifically,","Similarly,"],
  e:[null,"*Therefore* signals a result; losing the records would make reconstruction harder, not cause it.","*Specifically* gives a more exact version of the previous point; the volunteers' success is a new point that goes against it.","*Similarly* adds a matching point; the reconstruction is a success set against the loss, not another loss."],
  why:"Despite the fire and the damaged records, the volunteers succeeded: an outcome achieved in spite of what came before is introduced by nonetheless.",
  h:"Would you expect the volunteers to succeed, given the fire?" },
{ id:"a2h-12", t:"transition", d:"hum", lv:"C2", f:"transition", w:"accordingly",
  p:"The translator found that the novel's narrator speaks in short, plain sentences whenever she is afraid, and in long, winding ones whenever she feels safe. ______ the translator kept the length of every sentence exactly as it was in the original, even where this made the English sound unusual.",
  o:["Accordingly,","That said,","In other words,","Even so,"],
  e:[null,"*That said* introduces a point that limits the previous one; keeping the sentence lengths follows from her finding instead of limiting it.","*In other words* restates; her decision about sentence length is an action, not a restatement of the finding.","*Even so* introduces something done despite what came before; the translator kept the lengths because of her finding, not in spite of it."],
  why:"Because sentence length carries the narrator's feelings, the translator preserved it: a response that suits and follows from the finding is signalled by accordingly.",
  h:"Why did the translator keep the sentence lengths unchanged?" }
]
}
};
